<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/workspace.php';$farmer=require_role(['farmer']);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:filter_input(INPUT_POST,'listing_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$listing=$id?fetch_one('SELECT * FROM produce_listings WHERE id=:id AND farmer_id=:farmer LIMIT 1',['id'=>$id,'farmer'=>$farmer['id']]):null;if($listing===null){http_response_code(404);require __DIR__.'/../404.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=normalize_text($_POST['title']??'',160);$category=(int)($_POST['category_id']??0);$location=(int)($_POST['location_id']??0);$grade=normalize_text($_POST['grade']??'',10);$quantity=positive_decimal($_POST['quantity_available']??null);$price=positive_decimal($_POST['expected_price']??null);$minimum=positive_decimal($_POST['minimum_order_quantity']??null);$description=normalize_text($_POST['description']??'',1000);$harvest=($_POST['harvest_date']??'')?:null;$available=($_POST['available_from']??'')?:null;if(strlen($title)<3||$category<1||$location<1||!in_array($grade,['A','B','C','Mixed'],true)||$quantity===null||$price===null||$minimum===null||$minimum>$quantity)throw new RuntimeException('Enter valid listing terms; minimum order cannot exceed available quantity.');if(fetch_one('SELECT id FROM produce_categories WHERE id=:id AND is_active=1',['id'=>$category])===null||fetch_one('SELECT id FROM locations WHERE id=:id',['id'=>$location])===null)throw new RuntimeException('Choose an active category and valid location.');foreach([$harvest,$available] as $date)if($date!==null&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Use valid listing dates.');db()->prepare('UPDATE produce_listings SET category_id=:category,location_id=:location,title=:title,description=:description,grade=:grade,quantity_available=:quantity,expected_price=:price,harvest_date=:harvest,available_from=:available,minimum_order_quantity=:minimum WHERE id=:id AND farmer_id=:farmer')->execute(['category'=>$category,'location'=>$location,'title'=>$title,'description'=>$description?:null,'grade'=>$grade,'quantity'=>$quantity,'price'=>$price,'harvest'=>$harvest,'available'=>$available,'minimum'=>$minimum,'id'=>$id,'farmer'=>$farmer['id']]);audit_log((int)$farmer['id'],'produce_listing_edited','produce_listings',(int)$id,['fields'=>['category','location','title','description','grade','quantity','price','dates','minimum_order']]);flash('success','Listing details updated.');redirect('farmer/listings.php');}catch(Throwable $e){flash('error',$e->getMessage());}$listing=array_merge($listing,$_POST);}
$categories=fetch_all('SELECT id,name FROM produce_categories WHERE is_active=1 ORDER BY name');$locations=fetch_all('SELECT id,district,tehsil,area FROM locations ORDER BY district,tehsil');workspace_open('Edit produce listing','listings');
?>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Edit <?= e($listing['title']) ?></h2><p>Changes are account-scoped and immediately affect the active marketplace record.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_id" value="<?= (int)$id ?>"><label>Produce title<input name="title" maxlength="160" required value="<?= e($listing['title']) ?>"></label><label>Category<select name="category_id" required><?php foreach($categories as $category):?><option value="<?= (int)$category['id'] ?>" <?= (int)$listing['category_id']===(int)$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach;?></select></label><label>Origin<select name="location_id" required><?php foreach($locations as $location):?><option value="<?= (int)$location['id'] ?>" <?= (int)$listing['location_id']===(int)$location['id']?'selected':'' ?>><?= e($location['district'].' · '.$location['tehsil'].' · '.$location['area']) ?></option><?php endforeach;?></select></label><label>Grade<select name="grade"><?php foreach(['A','B','C','Mixed'] as $grade):?><option <?= $listing['grade']===$grade?'selected':'' ?>><?= e($grade) ?></option><?php endforeach;?></select></label><label>Quantity (kg)<input name="quantity_available" type="number" min="1" step=".01" value="<?= e((string)$listing['quantity_available']) ?>" required></label><label>Expected price (Rs./kg)<input name="expected_price" type="number" min="1" step=".01" value="<?= e((string)$listing['expected_price']) ?>" required></label><label>Minimum order (kg)<input name="minimum_order_quantity" type="number" min="1" step=".01" value="<?= e((string)$listing['minimum_order_quantity']) ?>" required></label><label>Harvest date<input name="harvest_date" type="date" value="<?= e($listing['harvest_date']??'') ?>"></label><label>Available from<input name="available_from" type="date" value="<?= e($listing['available_from']??'') ?>"></label><label>Description<textarea name="description" maxlength="1000" rows="4"><?= e($listing['description']??'') ?></textarea></label><div class="form-actions"><a class="button button-outline" href="<?= e(app_url('farmer/listings.php')) ?>">Cancel</a><button class="button button-primary" type="submit">Save changes</button></div></form></section>
<?php workspace_close(); ?>
